"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9080],{65765:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"","params":[{"name":"pathfinder","desc":"","lua_type":"Pathfinder"},{"name":"mover","desc":"","lua_type":"Mover"},{"name":"agent","desc":"Handed to `FindPath` so a pathfinder can read the blackboard.","lua_type":"Agent"},{"name":"options","desc":"","lua_type":"NavigationOptions?"},{"name":"steps","desc":"Handlers by step label.","lua_type":"{ [string]: StepHandler | StepRegistration }?"}],"returns":[{"desc":"","lua_type":"Navigator"}],"function_type":"static","source":{"line":115,"path":"lib/Navigator.luau"}},{"name":"MoveTo","desc":"Heads to `target`. Call it every tick with a moving target; a plan only happens when the\\ntarget is new, has moved more than `RepathDistance` since the last plan, the last plan failed\\nor ran out, the pathfinder reported the path blocked, or the path is older than `MaxPathAge`,\\nand never more often than `RepathInterval`. A new target after arriving is treated as new: the\\nstatus leaves `Arrived` at once.","params":[{"name":"self","desc":"","lua_type":"Navigator"},{"name":"target","desc":"","lua_type":"Vector3"}],"returns":[],"function_type":"static","source":{"line":567,"path":"lib/Navigator.luau"}},{"name":"Stop","desc":"Forgets the target and halts the mover. Fires `Arrived(false)` if a target was in progress.","params":[{"name":"self","desc":"","lua_type":"Navigator"}],"returns":[],"function_type":"static","source":{"line":603,"path":"lib/Navigator.luau"}},{"name":"GetStatus","desc":"","params":[{"name":"self","desc":"","lua_type":"Navigator"}],"returns":[{"desc":"","lua_type":"PathStatus"}],"function_type":"static","source":{"line":635,"path":"lib/Navigator.luau"}},{"name":"GetTarget","desc":"","params":[{"name":"self","desc":"","lua_type":"Navigator"}],"returns":[{"desc":"","lua_type":"Vector3?"}],"function_type":"static","source":{"line":643,"path":"lib/Navigator.luau"}},{"name":"GetPath","desc":"","params":[{"name":"self","desc":"","lua_type":"Navigator"}],"returns":[{"desc":"The last path planned, kept until the next plan or `Stop`.","lua_type":"Path?"}],"function_type":"static","source":{"line":651,"path":"lib/Navigator.luau"}},{"name":"Step","desc":"One tick. Retries a plan that is due even when nobody called `MoveTo` this tick, so a state\\nthat called `MoveTo` once with a fixed position still gets there after a stuck mover, a blocked\\npath or a path past `MaxPathAge`.","params":[{"name":"self","desc":"","lua_type":"Navigator"},{"name":"deltaTime","desc":"","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":663,"path":"lib/Navigator.luau"}},{"name":"Destroy","desc":"Stops and disconnects from the mover. The mover and pathfinder are not destroyed; the agent\\nowns those.","params":[{"name":"self","desc":"","lua_type":"Navigator"}],"returns":[],"function_type":"static","source":{"line":678,"path":"lib/Navigator.luau"}}],"properties":[],"types":[],"name":"Navigator","desc":"Owns a [Types.Pathfinder] and a [Types.Mover]. `MoveTo` is safe to call every tick with a\\nmoving target: the navigator re-plans on a cadence, re-plans when the target moves, retries when\\nthe mover gets stuck, and reports through `GetStatus` and `Arrived`. Every [Agent] built with\\nboth a pathfinder and a mover has one at `agent.Navigator`.\\n\\nA path to a target that stays put is followed to its end by default. Two options change that\\nfor a level that moves under the agent (doors, moving platforms, other NPCs): a pathfinder\\nwith a `Blocked` signal ([Navmesh] has one) makes the navigator re-plan on the next cadence\\ntick, and `MaxPathAge` plans again once the current path is that many seconds old, whether or\\nnot anything is known to have changed. Both cost one plan each time; neither plans more often\\nthan `RepathInterval`.\\n\\nArrival is judged by horizontal distance within `ArriveDistance`, with the height difference\\nallowed up to `ArriveHeight`: a humanoid\'s root and a floor waypoint sit at different heights,\\nbut a target on the floor above is not reached.\\n\\nA step whose `Label` has a handler (see [Builder:OnStep]) is where the navigator does the one\\nthing a mover cannot: it stops at the step, reports `Interacting`, runs the handler, and then\\nwalks the rest of the path. `MoveTo` with the same target keeps waiting; a new target or `Stop`\\nabandons the path and the handler\'s return is ignored.","source":{"line":105,"path":"lib/Navigator.luau"}}')}}]);